WITH by_dimension AS (SELECT p.brand, p.category, COUNT(*) AS rows_total, MAX(src.quantity) AS max_quantity FROM inventory src INNER JOIN products p ON src.product_id = p.id GROUP BY CUBE (p.brand, p.category)) SELECT brand, category, max_quantity, CASE WHEN brand RLIKE '^(Stark|Globex)$' THEN 'GROUP_B' ELSE 'EXTENDED' END AS brand_zone FROM by_dimension ORDER BY brand_zone NULLS FIRST
